const MODULES=[
{id:'m1',layer:'Camada 1 · Fundamentos',title:'Da coleta ao laudo',min:15,
 summary:'O que o aparelho mede, o que ele calcula e quais resultados são erro de coleta ou de leitura antes de serem doença.',
 goals:['Separar parâmetros medidos de parâmetros calculados.','Reconhecer os erros pré-analíticos mais comuns.','Saber quando pedir revisão em lâmina.'],
 sections:[
  {h:'As três séries',p:['O hemograma tem três partes: eritrograma (hemácias), leucograma (leucócitos, com a contagem diferencial) e plaquetograma. Leia sempre as três, mesmo quando a pergunta clínica é sobre uma só. Duas ou três séries alteradas juntas apontam para medula óssea, hiperesplenismo ou doença sistêmica.']},
  {h:'Medido ou calculado',table:{head:['Parâmetro','Como é obtido','Consequência prática'],rows:[['Hemoglobina','Medida direta por espectrofotometria','Mais confiável para definir anemia'],['Contagem de hemácias','Contagem direta','Entra no cálculo dos índices'],['VCM','Medido na maioria dos aparelhos','Classifica a anemia pelo tamanho'],['Hematócrito','Calculado: hemácias × VCM','Herda o erro dos dois'],['HCM e CHCM','Calculados a partir de hemoglobina, hemácias e hematócrito','Mudam junto com erros de leitura'],['RDW','Dispersão do volume das hemácias','Mede anisocitose']]}},
  {h:'Erros antes da doença',list:['Amostra coagulada ou coleta difícil: plaquetas falsamente baixas e, às vezes, hemoglobina alterada.','Pseudotrombocitopenia por EDTA: as plaquetas se agregam no tubo. Confirme em lâmina e repita em tubo com citrato.','Garrote prolongado e desidratação: hemoconcentração, com hemoglobina e hematócrito falsamente altos.','Coleta em braço com soro correndo: hemodiluição, todas as séries caem juntas.','Lipemia, hiperbilirrubinemia e leucocitose extrema: hemoglobina falsamente alta, com CHCM acima de 36 g/dL.','Crioaglutininas: hemácias aglutinadas contam como uma só. A contagem cai, o VCM e o CHCM sobem de forma absurda. Aquecer a amostra corrige.','Eritroblastos circulantes são contados como leucócitos em aparelhos antigos: a leucometria precisa ser corrigida.']},
  {h:'Quando pedir lâmina',p:['O esfregaço resolve o que o aparelho sinaliza e não explica: plaquetas baixas sem clínica, alertas de blastos ou de células atípicas, CHCM impossível, suspeita de hemólise ou de microangiopatia. Resultado que não combina com o paciente se repete antes de se investigar.']}
 ],
 pitfalls:['Tratar plaquetas de 40 mil sem sangramento sem antes confirmar em lâmina.','Interpretar hematócrito isolado em paciente desidratado.','Aceitar CHCM de 39 g/dL como real sem pensar em interferência ou esferocitose.','Comparar hemogramas de laboratórios diferentes sem olhar os valores de referência.','Ler só a série que motivou o exame.'],
 quiz:[
  {q:'Paciente assintomático com plaquetas de 38 mil no aparelho e agregados plaquetários na lâmina. O próximo passo é:',o:['Transfundir plaquetas','Repetir a coleta em tubo com citrato','Pedir mielograma','Iniciar corticoide'],a:1,why:'Agregados em amostra com EDTA indicam pseudotrombocitopenia. A contagem em citrato costuma normalizar.'},
  {q:'Hemograma com hemácias muito baixas, VCM de 130 fL e CHCM de 42 g/dL em paciente com pneumonia por Mycoplasma. A explicação mais provável é:',o:['Deficiência grave de B12','Crioaglutininas aglutinando as hemácias','Esferocitose hereditária','Erro de digitação'],a:1,why:'A aglutinação a frio faz o aparelho contar grumos como células únicas: poucas hemácias, grandes, com CHCM impossível.'},
  {q:'Qual parâmetro do eritrograma é medido diretamente e por isso define melhor a anemia?',o:['Hematócrito','Hemoglobina','CHCM','HCM'],a:1,why:'A hemoglobina é medida. O hematócrito é calculado a partir da contagem de hemácias e do VCM.'}
 ],refs:['guia']},

{id:'m2',layer:'Camada 1 · Fundamentos',title:'Eritrograma e índices hematimétricos',min:20,
 summary:'O que cada índice quer dizer e como VCM, RDW e reticulócitos organizam o raciocínio.',
 goals:['Interpretar VCM, HCM, CHCM e RDW.','Calcular e interpretar os reticulócitos corrigidos.','Usar o RDW para separar causas de microcitose.'],
 sections:[
  {h:'Os índices',table:{head:['Índice','O que mede','Referência no adulto','Leitura'],rows:[['VCM','Volume médio da hemácia','80 a 100 fL','Abaixo: microcitose. Acima: macrocitose'],['HCM','Hemoglobina por hemácia','27 a 32 pg','Baixo: hipocromia'],['CHCM','Concentração de hemoglobina na hemácia','32 a 36 g/dL','Alto de verdade: esferocitose. Alto falso: interferência'],['RDW','Variação do volume das hemácias','11,5 a 14,5%','Alto: populações de tamanhos diferentes']]},after:'Os valores de referência variam entre laboratórios. Use os do laudo.'},
  {h:'VCM e RDW juntos',table:{head:['Combinação','Pensar em'],rows:[['VCM baixo, RDW alto','Ferropenia'],['VCM baixo, RDW normal','Traço talassêmico, doença crônica'],['VCM alto, RDW alto','Deficiência de B12 ou folato'],['VCM alto, RDW normal','Álcool, hepatopatia, medicamentos, aplasia'],['VCM normal, RDW alto','Deficiência mista, ferropenia inicial, pós-transfusão, anemia falciforme']]},after:'VCM normal com RDW alto pode esconder duas populações: uma microcítica e outra macrocítica, que se anulam na média.'},
  {h:'Reticulócitos',p:['Os reticulócitos dizem se a medula está respondendo. Anemia com reticulócitos altos é perda ou destruição: sangramento ou hemólise. Anemia com reticulócitos baixos ou normais é falta de produção.','A porcentagem bruta engana, porque há menos hemácias no denominador. Use a contagem absoluta (acima de 100 mil por microlitro indica resposta) ou o índice de produção reticulocitária.'],list:['Reticulócitos corrigidos = reticulócitos (%) × hematócrito do paciente ÷ 45.','Índice de produção = reticulócitos corrigidos ÷ fator de maturação (1 para hematócrito de 45%; 1,5 para 35%; 2 para 25%; 2,5 para 15%).','Índice acima de 2: medula respondendo. Abaixo de 2: resposta insuficiente para o grau de anemia.']},
  {h:'Hemácias, hemoglobina e a regra de três',p:['Em amostra sem interferência, a hemoglobina é cerca de um terço do hematócrito, e a contagem de hemácias (em milhões) vezes três fica perto da hemoglobina. Quando a regra quebra, há microcitose importante, macrocitose importante ou erro de leitura.']}
 ],
 pitfalls:['Dizer que a medula responde porque os reticulócitos estão em 3%, sem corrigir pelo hematócrito.','Esquecer que reticulocitose aumenta o VCM: hemólise pode dar macrocitose leve.','Usar HCM e CHCM como sinônimos.','Ignorar RDW alto com VCM normal.','Classificar a anemia só pelo VCM sem olhar os reticulócitos.'],
 quiz:[
  {q:'Hematócrito de 25% e reticulócitos de 6%. O índice de produção reticulocitária é aproximadamente:',o:['6','3,3','1,7','0,5'],a:2,why:'Corrigidos: 6 × 25 ÷ 45 = 3,3. Dividido pelo fator de maturação 2 = 1,7. Resposta ainda insuficiente.'},
  {q:'VCM de 68 fL com RDW de 13% e contagem de hemácias de 5,9 milhões em paciente assintomático. O mais provável é:',o:['Ferropenia','Traço talassêmico','Deficiência de B12','Anemia de doença crônica'],a:1,why:'Microcitose desproporcional, com muitas hemácias e RDW normal, é o padrão do traço talassêmico.'},
  {q:'CHCM verdadeiramente elevado sugere:',o:['Ferropenia','Esferocitose','Talassemia','Deficiência de folato'],a:1,why:'O esferócito perde membrana e concentra a hemoglobina. As demais causas reduzem ou não alteram o CHCM.'}
 ],refs:['guia']},

{id:'m3',layer:'Camada 2 · Série vermelha',title:'Abordagem das anemias',min:20,
 summary:'Definir anemia, decidir se é falta de produção ou perda e escolher o primeiro exame.',
 goals:['Aplicar os pontos de corte de hemoglobina da OMS.','Seguir a sequência reticulócitos, VCM, cinética do ferro.','Reconhecer quando a anemia é urgência.'],
 sections:[
  {h:'Quando é anemia',table:{head:['População','Anemia se hemoglobina abaixo de'],rows:[['Homens (15 a 65 anos)','13,0 g/dL'],['Mulheres não gestantes','12,0 g/dL'],['Gestantes, 1º trimestre','11,0 g/dL'],['Gestantes, 2º trimestre','10,5 g/dL'],['Gestantes, 3º trimestre','11,0 g/dL']]},after:'Valores da diretriz da OMS de 2024, que manteve os cortes de adultos e passou a separar a gestação por trimestre. Altitude e tabagismo elevam a hemoglobina e pedem ajuste.'},
  {h:'A sequência',list:['1. Confirme: é só a série vermelha ou há outras séries alteradas? Bicitopenia e pancitopenia mudam a investigação.','2. Reticulócitos: altos indicam sangramento ou hemólise; baixos indicam falta de produção.','3. VCM: micro, normo ou macrocítica.','4. Exame dirigido: ferritina e saturação de transferrina na microcítica; B12 e folato na macrocítica; função renal, provas inflamatórias e provas de hemólise na normocítica.','5. Esfregaço sempre que o quadro não fechar.']},
  {h:'Gravidade e urgência',p:['A gravidade depende mais da velocidade de instalação e da reserva do paciente do que do número. Anemia crônica de 7 g/dL pode ser bem tolerada; queda aguda para 9 g/dL com sangramento ativo pode ser choque.','Procure sinais de instabilidade: taquicardia, hipotensão postural, angina, dispneia em repouso, alteração do nível de consciência.']},
  {h:'Transfusão',p:['Em adulto internado e estável, a estratégia restritiva transfunde quando a hemoglobina está abaixo de 7 g/dL. Em cardiopatas e em cirurgia cardíaca ou ortopédica, o limiar costuma ser 7,5 a 8 g/dL. Sintoma e sangramento ativo pesam mais que o número. Anemia carencial crônica estável se trata com reposição, não com sangue.']}
 ],
 pitfalls:['Tratar o número com ferro sem saber a causa.','Esquecer que ferropenia em homem ou em mulher após a menopausa exige procurar sangramento digestivo.','Chamar de anemia de doença crônica sem dosar ferritina.','Transfundir anemia carencial crônica e assintomática.','Não pedir reticulócitos.'],
 quiz:[
  {q:'Gestante de 24 semanas com hemoglobina de 10,7 g/dL. Pela diretriz da OMS de 2024:',o:['Tem anemia leve','Não tem anemia','Tem anemia moderada','O valor não pode ser interpretado na gestação'],a:1,why:'No segundo trimestre o corte é 10,5 g/dL, por causa da hemodiluição fisiológica.'},
  {q:'Anemia com reticulócitos corrigidos altos. As duas grandes hipóteses são:',o:['Ferropenia e doença crônica','Sangramento e hemólise','Deficiência de B12 e de folato','Aplasia e mielodisplasia'],a:1,why:'Medula que responde indica perda ou destruição periférica.'},
  {q:'Homem de 62 anos, estável, sem sangramento visível, hemoglobina de 8,4 g/dL, VCM de 72 fL, ferritina de 9 ng/mL. A conduta que não pode faltar é:',o:['Transfundir','Investigar o trato gastrointestinal','Dosar B12','Pedir eletroforese de hemoglobina'],a:1,why:'Ferropenia em homem adulto é perda digestiva até prova em contrário: endoscopia e colonoscopia.'}
 ],refs:['who2024','aabb2023','guia']},

{id:'m4',layer:'Camada 2 · Série vermelha',title:'Anemias microcíticas',min:25,
 summary:'Ferropenia, doença crônica, talassemia e sideroblástica: como a cinética do ferro separa as quatro.',
 goals:['Interpretar ferritina, ferro sérico, saturação de transferrina e capacidade de ligação.','Diferenciar ferropenia de traço talassêmico.','Definir a investigação da causa da ferropenia.'],
 sections:[
  {h:'As quatro causas',table:{head:['Causa','Ferritina','Ferro sérico','Capacidade de ligação','Saturação','Pista'],rows:[['Ferropenia','Baixa','Baixo','Alta','Baixa','RDW alto, plaquetas altas'],['Doença crônica','Normal ou alta','Baixo','Baixa ou normal','Baixa ou normal','Inflamação, PCR alta'],['Traço talassêmico','Normal','Normal','Normal','Normal','Muitas hemácias, RDW normal'],['Sideroblástica','Alta','Alto','Normal','Alta','Pontilhado basofílico, chumbo, álcool, isoniazida']]}},
  {h:'Ferritina',p:['A ferritina é o melhor exame isolado para ferropenia. Abaixo de 30 ng/mL confirma na prática; a diretriz da AGA usa 45 ng/mL como corte em quem tem anemia. Como é proteína de fase aguda, sobe na inflamação: nesse contexto, valores até 100 ng/mL ainda são compatíveis com deficiência, e a saturação de transferrina abaixo de 20% ajuda.']},
  {h:'Ferropenia em etapas',list:['Depleção dos estoques: ferritina cai, hemograma normal.','Eritropoese deficiente em ferro: saturação cai, RDW sobe.','Anemia: primeiro normocítica, depois microcítica e hipocrômica.','Clínica que orienta: pica, queilite angular, coiloníquia, glossite, queda de cabelo.','Trombocitose reacional é comum e some com o tratamento.']},
  {h:'Procurar a causa',p:['Ferropenia é diagnóstico incompleto. Em mulher em idade fértil, a perda menstrual é a causa mais comum. Em homens e em mulheres após a menopausa, a diretriz recomenda endoscopia e colonoscopia. Lembre também de doença celíaca, gastrite atrófica, cirurgia bariátrica, uso de inibidor de bomba de prótons, parasitoses e dieta.']},
  {h:'Talassemia ou ferropenia',list:['Índice de Mentzer (VCM ÷ hemácias em milhões): abaixo de 13 sugere traço talassêmico; acima de 13 sugere ferropenia.','Traço beta: hemoglobina A2 acima de 3,5% na eletroforese.','Traço alfa: eletroforese normal no adulto; o diagnóstico é de exclusão ou genético.','Ferropenia associada reduz a hemoglobina A2 e pode mascarar o traço beta: corrija o ferro e repita.']},
  {h:'Tratamento da ferropenia',p:['Ferro oral em dose única diária ou em dias alternados, que absorve tão bem ou melhor e causa menos efeito digestivo. Os reticulócitos sobem em 7 a 10 dias e a hemoglobina sobe cerca de 1 g/dL a cada 2 a 3 semanas. Mantenha por 3 meses depois de normalizar para repor os estoques. Ferro venoso entra na intolerância, na má absorção, na doença inflamatória intestinal ativa, na doença renal crônica e quando a perda supera a reposição oral.']}
 ],
 pitfalls:['Dar ferro a paciente com traço talassêmico sem ferropenia comprovada.','Considerar ferritina de 60 ng/mL normal em paciente com artrite reumatoide ativa.','Suspender o ferro quando a hemoglobina normaliza.','Não investigar o trato digestivo em homem com ferropenia.','Pedir eletroforese de hemoglobina com ferropenia não corrigida e descartar traço beta.'],
 quiz:[
  {q:'VCM de 70 fL, ferritina de 180 ng/mL, ferro sérico baixo, capacidade de ligação baixa, PCR elevada. O diagnóstico mais provável é:',o:['Ferropenia','Anemia de doença crônica','Traço talassêmico','Anemia sideroblástica'],a:1,why:'Ferro baixo com ferritina alta e capacidade de ligação baixa é o padrão de sequestro de ferro pela inflamação.'},
  {q:'VCM de 66 fL e 6,1 milhões de hemácias. O índice de Mentzer é cerca de 10,8. Isso sugere:',o:['Ferropenia','Traço talassêmico','Deficiência de B12','Hemólise'],a:1,why:'Índice abaixo de 13 fala a favor de talassemia: muitas hemácias pequenas.'},
  {q:'Paciente em reposição de ferro oral há 10 dias. O primeiro sinal laboratorial de resposta é:',o:['Aumento do VCM','Aumento dos reticulócitos','Normalização da ferritina','Queda das plaquetas'],a:1,why:'O pico reticulocitário aparece entre 7 e 10 dias. A hemoglobina sobe depois, e a ferritina é a última a normalizar.'}
 ],refs:['aga2020','guia']},

{id:'m5',layer:'Camada 2 · Série vermelha',title:'Anemias macrocíticas',min:20,
 summary:'Separar megaloblástica de não megaloblástica e não perder a deficiência de B12 com quadro neurológico.',
 goals:['Diferenciar macrocitose megaloblástica da não megaloblástica.','Interpretar B12, folato, ácido metilmalônico e homocisteína.','Reconhecer mielodisplasia entre as macrocitoses do idoso.'],
 sections:[
  {h:'Dois grupos',table:{head:['Grupo','Causas','Pistas'],rows:[['Megaloblástica','Deficiência de B12, deficiência de folato, hidroxiureia, metotrexato, zidovudina','VCM muitas vezes acima de 110 fL, macro-ovalócitos, neutrófilos hipersegmentados, pancitopenia leve, LDH e bilirrubina indireta altas'],['Não megaloblástica','Álcool, hepatopatia, hipotireoidismo, reticulocitose, mielodisplasia, aplasia','VCM em geral até 110 fL, macrócitos redondos, sem hipersegmentação']]}},
  {h:'B12 e folato',list:['B12 abaixo de 200 pg/mL: deficiência provável. Entre 200 e 300 pg/mL: zona cinzenta, dose ácido metilmalônico e homocisteína.','Ácido metilmalônico alto com homocisteína alta: deficiência de B12. Só homocisteína alta: deficiência de folato.','Causas de deficiência de B12: anemia perniciosa (anticorpos antifator intrínseco e anticélula parietal), gastrectomia e bariátrica, doença ou ressecção ileal, metformina, inibidor de bomba de prótons por tempo longo, dieta vegana estrita.','Causas de deficiência de folato: dieta pobre, álcool, gestação, hemólise crônica, metotrexato, fenitoína, sulfametoxazol com trimetoprima.']},
  {h:'O quadro neurológico',p:['Só a deficiência de B12 lesa o sistema nervoso: parestesias, perda de sensibilidade vibratória e de propriocepção, ataxia, declínio cognitivo. O quadro neurológico pode vir antes da anemia e sem macrocitose. Repor folato em quem tem deficiência de B12 corrige o sangue e deixa a lesão neurológica progredir. Na dúvida, dose os dois e reponha B12.']},
  {h:'Macrocitose no idoso sem causa',p:['Macrocitose com citopenias, sem deficiência vitamínica, sem álcool e sem medicamento que explique, levanta a suspeita de síndrome mielodisplásica. O esfregaço pode mostrar neutrófilos hipogranulares ou com núcleo bilobado (pseudo-Pelger). O passo seguinte é o mielograma com citogenética.']},
  {h:'Resposta ao tratamento',p:['Com B12 parenteral, os reticulócitos sobem em 3 a 5 dias e atingem o pico em uma semana. Nos primeiros dias pode haver hipocalemia, pelo consumo de potássio na produção de células. Se a hemoglobina não normalizar em 6 a 8 semanas, procure ferropenia associada.']}
 ],
 pitfalls:['Repor só folato sem ter afastado deficiência de B12.','Descartar deficiência de B12 porque o hemograma está normal em paciente com neuropatia.','Atribuir macrocitose ao álcool sem dosar vitaminas.','Esquecer metformina e inibidor de bomba de prótons como causas.','Não pensar em mielodisplasia no idoso com macrocitose e outra citopenia.'],
 quiz:[
  {q:'VCM de 118 fL, neutrófilos hipersegmentados, LDH muito alto e bilirrubina indireta elevada. O mecanismo é:',o:['Hemólise autoimune','Eritropoese ineficaz com destruição intramedular','Sangramento oculto','Hiperesplenismo'],a:1,why:'Na anemia megaloblástica os precursores morrem dentro da medula, o que eleva LDH e bilirrubina indireta.'},
  {q:'B12 de 240 pg/mL em paciente com parestesias. O exame que confirma a deficiência é:',o:['Folato sérico','Ácido metilmalônico','Ferritina','Reticulócitos'],a:1,why:'Na zona cinzenta, ácido metilmalônico elevado confirma deficiência tecidual de B12.'},
  {q:'Idoso com VCM de 104 fL, plaquetas de 90 mil, B12 e folato normais, sem álcool. A hipótese que precisa ser investigada é:',o:['Ferropenia','Síndrome mielodisplásica','Traço talassêmico','Anemia de doença crônica'],a:1,why:'Macrocitose com outra citopenia e sem causa carencial ou tóxica pede avaliação medular.'}
 ],refs:['bsh2014','guia']},

{id:'m6',layer:'Camada 2 · Série vermelha',title:'Anemias normocíticas e hemólise',min:25,
 summary:'O grupo mais heterogêneo: reticulócitos e provas de hemólise fazem a triagem.',
 goals:['Organizar as normocíticas pelos reticulócitos.','Reconhecer o perfil laboratorial de hemólise.','Separar hemólise imune de microangiopática.'],
 sections:[
  {h:'Com reticulócitos baixos',list:['Anemia de doença crônica ou da inflamação: a mais comum em internados.','Doença renal crônica: falta de eritropoetina, em geral com taxa de filtração abaixo de 30 a 45 mL/min.','Ferropenia ou deficiência de B12 em fase inicial, ou deficiência mista.','Endócrinas: hipotireoidismo, insuficiência adrenal, hipogonadismo.','Medula: aplasia, infiltração, aplasia pura de série vermelha (parvovírus B19, timoma).']},
  {h:'Com reticulócitos altos',p:['Restam sangramento agudo e hemólise. No sangramento agudo, a hemoglobina demora horas para cair, porque se perdem plasma e hemácias na mesma proporção: o primeiro hemograma pode enganar.']},
  {h:'Perfil de hemólise',table:{head:['Exame','Na hemólise'],rows:[['Reticulócitos','Altos'],['LDH','Alto'],['Bilirrubina indireta','Alta'],['Haptoglobina','Baixa ou indetectável'],['Hemoglobinúria e hemossiderinúria','Presentes na hemólise intravascular'],['Esfregaço','Esferócitos, esquizócitos, policromasia, conforme a causa']]}},
  {h:'Qual hemólise',table:{head:['Achado','Diagnóstico provável','Confirmação'],rows:[['Esferócitos e Coombs direto positivo','Anemia hemolítica autoimune','IgG: anticorpos quentes. C3: anticorpos frios'],['Esferócitos e Coombs negativo, história familiar','Esferocitose hereditária','Teste de fragilidade osmótica ou EMA'],['Esquizócitos e plaquetas baixas','Microangiopatia: PTT, SHU, CIVD, HELLP, hipertensão maligna','ADAMTS13, coagulograma, função renal'],['Esquizócitos sem plaquetopenia','Hemólise mecânica por prótese valvar','Ecocardiograma'],['Células mordidas e corpúsculos de Heinz após droga ou infecção','Deficiência de G6PD','Dosagem enzimática fora da crise'],['Drepanócitos','Doença falciforme','Eletroforese de hemoglobina']]}},
  {h:'Anemia da inflamação',p:['A hepcidina, estimulada pela interleucina 6, bloqueia a saída de ferro dos estoques e a absorção intestinal. O resultado é ferro sérico baixo com ferritina normal ou alta. Em geral a hemoglobina fica entre 8 e 10 g/dL. Valores menores pedem outra causa associada. O tratamento é o da doença de base.']}
 ],
 pitfalls:['Dosar G6PD durante a crise hemolítica: os reticulócitos têm mais enzima e o resultado sai falsamente normal.','Confiar no primeiro hemograma em sangramento agudo.','Esquecer de olhar as plaquetas quando há esquizócitos.','Atribuir à inflamação uma hemoglobina de 6 g/dL.','Não pedir Coombs direto diante de esferócitos.'],
 quiz:[
  {q:'Anemia com LDH alto, haptoglobina indetectável, esquizócitos e plaquetas de 22 mil. O exame que define a conduta de urgência é:',o:['Coombs direto','Atividade de ADAMTS13','Eletroforese de hemoglobina','Ferritina'],a:1,why:'Microangiopatia com plaquetopenia grave é PTT até prova em contrário. A plasmaférese não espera o resultado quando a suspeita é alta.'},
  {q:'Paciente com hemólise após uso de primaquina. A dosagem de G6PD colhida na crise veio normal. A conduta é:',o:['Excluir a deficiência','Repetir a dosagem semanas depois da crise','Pedir Coombs','Indicar esplenectomia'],a:1,why:'Na crise, as hemácias deficientes já foram destruídas e os reticulócitos elevam a atividade medida.'},
  {q:'Anemia normocítica com ferro baixo, ferritina de 350 ng/mL e capacidade de ligação baixa em paciente com tuberculose. O mediador central é:',o:['Eritropoetina','Hepcidina','Fator intrínseco','Haptoglobina'],a:1,why:'A hepcidina retém o ferro em macrófagos e reduz a absorção intestinal.'}
 ],refs:['guia','isth2020']},

{id:'m7',layer:'Camada 2 · Série vermelha',title:'Eritrocitose',min:15,
 summary:'Hemoglobina alta: desidratação, hipóxia ou policitemia vera.',
 goals:['Separar eritrocitose relativa de absoluta.','Usar eritropoetina e JAK2 para separar causas primárias de secundárias.','Reconhecer as pistas de policitemia vera no hemograma.'],
 sections:[
  {h:'Relativa ou absoluta',p:['Na eritrocitose relativa, a massa de hemácias é normal e o plasma está reduzido: desidratação, diuréticos, grandes queimados. Corrigida a volemia, o hematócrito volta. Na absoluta, a massa de hemácias está de fato aumentada.']},
  {h:'Primária ou secundária',table:{head:['Tipo','Eritropoetina','Causas'],rows:[['Primária','Baixa','Policitemia vera'],['Secundária por hipóxia','Alta','DPOC, apneia do sono, tabagismo, altitude, cardiopatia com shunt'],['Secundária sem hipóxia','Alta','Tumor produtor de eritropoetina (rim, fígado, hemangioblastoma), cistos renais, estenose de artéria renal, testosterona e anabolizantes']]}},
  {h:'Policitemia vera',list:['Critério de hemoglobina: acima de 16,5 g/dL em homens ou 16,0 g/dL em mulheres, ou hematócrito acima de 49% e 48%.','Mutação de JAK2 presente em mais de 95% dos casos.','Eritropoetina sérica baixa.','Pistas no hemograma: leucocitose e trombocitose associadas.','Pistas clínicas: prurido após banho quente, eritromelalgia, pletora, esplenomegalia, trombose em local incomum.','Risco principal: trombose arterial e venosa. A meta de tratamento é hematócrito abaixo de 45%.']},
  {h:'Investigação',p:['Repita o exame com o paciente hidratado. Confirmada a eritrocitose, pergunte por tabagismo, ronco, uso de testosterona e doença pulmonar, meça a saturação e peça eritropoetina e JAK2. Eritropoetina baixa com JAK2 positivo é policitemia vera. Eritropoetina alta leva à busca de hipóxia ou de tumor.']}
 ],
 pitfalls:['Diagnosticar policitemia em paciente desidratado.','Esquecer de perguntar por testosterona e anabolizantes.','Ignorar ferropenia associada, que reduz a hemoglobina e mascara a policitemia vera: o VCM baixo com muitas hemácias é a pista.','Indicar sangria em eritrocitose por hipóxia sem tratar a causa.','Não pedir JAK2 quando há leucocitose e trombocitose junto.'],
 quiz:[
  {q:'Homem com hemoglobina de 18,9 g/dL, plaquetas de 620 mil, leucócitos de 14 mil e prurido após o banho. O exame mais útil é:',o:['Gasometria arterial','Pesquisa de mutação de JAK2','Ferritina','Eletroforese de hemoglobina'],a:1,why:'Panmielose com prurido aquagênico é o quadro típico de policitemia vera.'},
  {q:'Eritrocitose com eritropoetina elevada e saturação de oxigênio normal acordado. Duas causas a procurar são:',o:['Policitemia vera e ferropenia','Apneia do sono e tumor renal','Desidratação e diurético','Talassemia e hemólise'],a:1,why:'Eritropoetina alta indica causa secundária: hipóxia intermitente noturna ou produção tumoral.'},
  {q:'Na policitemia vera, a meta de hematócrito para reduzir trombose é:',o:['Abaixo de 55%','Abaixo de 50%','Abaixo de 45%','Abaixo de 35%'],a:2,why:'O controle abaixo de 45% reduziu eventos cardiovasculares e é a meta adotada.'}
 ],refs:['who2022','guia']},

{id:'m8',layer:'Camada 3 · Série branca',title:'Leucocitose, neutrofilia e neutropenia',min:25,
 summary:'Ler o diferencial em números absolutos, separar reação de leucemia e reconhecer a neutropenia febril.',
 goals:['Calcular valores absolutos do diferencial.','Diferenciar reação leucemoide de leucemia mieloide crônica.','Classificar neutropenia e reconhecer neutropenia febril.'],
 sections:[
  {h:'Sempre em valor absoluto',p:['A porcentagem engana. Linfócitos de 60% com 3 mil leucócitos são 1.800 linfócitos: o problema é a neutropenia, não a linfocitose. Multiplique a porcentagem pela leucometria total.'],table:{head:['Célula','Referência no adulto (por microlitro)'],rows:[['Leucócitos totais','4.000 a 11.000'],['Neutrófilos','1.500 a 7.500'],['Linfócitos','1.000 a 4.000'],['Monócitos','200 a 1.000'],['Eosinófilos','até 500'],['Basófilos','até 100']]},after:'Os intervalos variam entre laboratórios.'},
  {h:'Neutrofilia',list:['Infecção bacteriana, inflamação, necrose tecidual, queimadura.','Corticoide: desmargina neutrófilos, sem desvio à esquerda e com eosinopenia e linfopenia.','Estresse, exercício, dor, convulsão, tabagismo, gestação.','Lítio, fator estimulador de colônias, adrenalina.','Neoplasias mieloproliferativas.'],after:'Desvio à esquerda é o aumento de formas jovens (bastões, metamielócitos). Granulações tóxicas, vacúolos e corpúsculos de Döhle reforçam infecção. Desvio à esquerda com leucócitos baixos em paciente séptico indica consumo e é sinal de gravidade.'},
  {h:'Reação leucemoide ou leucemia mieloide crônica',table:{head:['Característica','Reação leucemoide','Leucemia mieloide crônica'],rows:[['Leucometria','Acima de 50 mil, com causa aparente','Muitas vezes acima de 100 mil'],['Diferencial','Neutrófilos e bastões','Todas as fases de maturação, com pico de mielócitos'],['Basófilos e eosinófilos','Normais ou baixos','Aumentados'],['Granulações tóxicas','Presentes','Ausentes'],['Baço','Normal','Aumentado'],['Fosfatase alcalina leucocitária','Alta','Baixa'],['Confirmação','Tratar a causa e repetir','BCR-ABL1 ou cromossomo Filadélfia']]}},
  {h:'Blastos',p:['Blastos no sangue periférico são sinal de alarme. Leucocitose com blastos, anemia e plaquetopenia sugere leucemia aguda. Bastões de Auer indicam linhagem mieloide. Pancitopenia com sangramento desproporcional e CIVD levanta a suspeita de leucemia promielocítica, que é urgência.']},
  {h:'Neutropenia',table:{head:['Grau','Neutrófilos por microlitro','Risco'],rows:[['Leve','1.000 a 1.500','Pequeno'],['Moderada','500 a 1.000','Aumentado'],['Grave','Abaixo de 500','Alto: infecção bacteriana e fúngica']]},after:'Causas: medicamentos (dipirona, metimazol, clozapina, sulfas, quimioterápicos), infecções virais, sepse, deficiência de B12 e folato, hiperesplenismo, doenças autoimunes, falência medular. Neutropenia étnica benigna existe e não aumenta infecção.'},
  {h:'Neutropenia febril',p:['Temperatura oral de 38,3 °C em medida única, ou de 38,0 °C mantida por uma hora, com neutrófilos abaixo de 500, ou com queda prevista para abaixo de 500 em 48 horas. É emergência: colher culturas e iniciar betalactâmico com ação contra Pseudomonas na primeira hora. O exame físico pode ser pobre, porque sem neutrófilos não há pus.']}
 ],
 pitfalls:['Ler linfocitose relativa como linfocitose.','Atribuir toda leucocitose a infecção em paciente que usa corticoide.','Esperar foco infeccioso evidente para tratar neutropenia febril.','Confundir leucocitose com basofilia e esplenomegalia com reação a infecção.','Não revisar os medicamentos diante de neutropenia nova.'],
 quiz:[
  {q:'Leucócitos de 2.400 com 20% de neutrófilos e 2% de bastões. A contagem absoluta de neutrófilos é:',o:['240','528','1.200','2.000'],a:1,why:'Neutrófilos mais bastões: 22% de 2.400 = 528. Neutropenia moderada, quase grave.'},
  {q:'Leucometria de 140 mil com mielócitos, metamielócitos, basofilia e esplenomegalia em paciente sem febre. O exame que confirma é:',o:['Hemocultura','Pesquisa de BCR-ABL1','Fosfatase alcalina sérica','Coombs direto'],a:1,why:'Desvio escalonado com basofilia e baço aumentado é leucemia mieloide crônica.'},
  {q:'Paciente em quimioterapia, temperatura de 38,5 °C, neutrófilos de 300, sem foco aparente. A conduta é:',o:['Aguardar culturas para iniciar antibiótico','Colher culturas e iniciar antibiótico de amplo espectro em até uma hora','Dar antitérmico e reavaliar em 24 horas','Iniciar apenas antifúngico'],a:1,why:'Neutropenia febril se trata de forma empírica e imediata.'}
 ],refs:['idsa2011','who2022','guia']},

{id:'m9',layer:'Camada 3 · Série branca',title:'Linfócitos, eosinófilos, monócitos e basófilos',min:20,
 summary:'O que cada alteração do diferencial sugere e quando ela é clonal.',
 goals:['Separar linfocitose reacional de clonal.','Investigar eosinofilia de forma ordenada.','Dar significado a monocitose, basofilia e linfopenia.'],
 sections:[
  {h:'Linfocitose',table:{head:['Padrão','Pensar em','Pista'],rows:[['Jovem, febre, faringite, linfócitos atípicos','Mononucleose (EBV), CMV, HIV agudo, toxoplasmose','Linfócitos grandes, de citoplasma basofílico'],['Criança com tosse paroxística','Coqueluche','Linfócitos pequenos e maduros'],['Idoso, assintomático, linfócitos maduros e manchas de Gumprecht','Leucemia linfocítica crônica','Linfonodos, baço'],['Estresse agudo, pós-esplenectomia, tabagismo','Reacional','Transitória ou estável']]},after:'O diagnóstico de leucemia linfocítica crônica exige pelo menos 5 mil linfócitos B clonais por microlitro, mantidos por 3 meses ou mais, confirmados por imunofenotipagem.'},
  {h:'Linfopenia',list:['HIV, corticoide, quimioterapia e radioterapia.','Sepse e doença grave aguda.','Lúpus e outras doenças autoimunes.','Desnutrição, insuficiência renal, linfoma de Hodgkin.','Linfopenia persistente sem causa pede sorologia para HIV.']},
  {h:'Eosinofilia',p:['Acima de 500 por microlitro. A partir de 1.500 já se fala em hipereosinofilia, com risco de lesão de órgãos (coração, pulmão, nervos, pele).'],list:['Alergia: asma, rinite, dermatite atópica.','Parasitoses com fase tecidual: estrongiloidíase, ascaridíase, ancilostomíase, esquistossomose, toxocaríase.','Medicamentos, incluindo a síndrome DRESS.','Insuficiência adrenal.','Vasculite: granulomatose eosinofílica com poliangiite.','Neoplasias: linfoma de Hodgkin, leucemia eosinofílica, neoplasias mieloides com rearranjo de PDGFRA.'],after:'Antes de dar corticoide a quem tem eosinofilia e viveu em área endêmica, afaste ou trate estrongiloidíase, pelo risco de hiperinfecção.'},
  {h:'Monocitose e basofilia',p:['Monocitose (acima de mil) aparece na recuperação medular, em infecções crônicas como tuberculose e endocardite, em doenças inflamatórias e, quando persistente por mais de 3 meses no idoso, na leucemia mielomonocítica crônica. Basofilia é rara e, quando verdadeira e persistente, sugere neoplasia mieloproliferativa, sobretudo leucemia mieloide crônica.']}
 ],
 pitfalls:['Chamar de leucemia a linfocitose com linfócitos atípicos em jovem com faringite.','Dar corticoide para eosinofilia sem pensar em Strongyloides.','Esquecer HIV na linfopenia sem causa.','Ignorar monocitose persistente no idoso.','Não pedir imunofenotipagem em linfocitose mantida.'],
 quiz:[
  {q:'Homem de 70 anos, assintomático, com 28 mil linfócitos maduros e manchas de Gumprecht. O exame que confirma o diagnóstico é:',o:['Mielograma','Imunofenotipagem do sangue periférico','Sorologia para EBV','Biópsia de linfonodo'],a:1,why:'A citometria demonstra a população B clonal e fecha leucemia linfocítica crônica sem necessidade de medula.'},
  {q:'Paciente de área rural com eosinófilos de 2.300 vai iniciar prednisona em dose alta. Antes, é preciso:',o:['Dosar IgE','Afastar ou tratar estrongiloidíase','Pedir ecocardiograma','Iniciar anti-histamínico'],a:1,why:'O corticoide pode desencadear hiperinfecção por Strongyloides, com alta mortalidade.'},
  {q:'Leucócitos de 3.200 com 62% de linfócitos. A interpretação correta é:',o:['Linfocitose','Linfócitos normais em valor absoluto, com neutropenia','Leucemia linfocítica crônica','Infecção viral confirmada'],a:1,why:'São 1.984 linfócitos, dentro do normal. A alteração real é a queda dos neutrófilos.'}
 ],refs:['iwcll','guia']},

{id:'m10',layer:'Camada 4 · Plaquetas',title:'Trombocitopenia e trombocitose',min:25,
 summary:'Confirmar, estimar o risco de sangramento e não perder as causas que matam: PTT, HIT e CIVD.',
 goals:['Confirmar plaquetopenia verdadeira.','Organizar as causas por mecanismo.','Reconhecer PTT, HIT e CIVD e a conduta inicial de cada uma.'],
 sections:[
  {h:'Primeiro, confirmar',p:['Plaquetas abaixo de 150 mil. Antes de investigar, afaste pseudotrombocitopenia: lâmina e nova coleta em citrato. Plaquetas gigantes também são subcontadas pelo aparelho.']},
  {h:'Número e risco',table:{head:['Plaquetas por microlitro','Risco habitual'],rows:[['Acima de 50 mil','Em geral sem sangramento espontâneo; maioria dos procedimentos é possível'],['20 a 50 mil','Sangramento com trauma ou procedimento'],['10 a 20 mil','Sangramento espontâneo possível'],['Abaixo de 10 mil','Risco de sangramento grave; limiar habitual de transfusão profilática na falência de produção']]},after:'O risco depende também da causa, da função plaquetária, de febre e de anticoagulantes.'},
  {h:'Causas por mecanismo',list:['Produção reduzida: quimioterapia, álcool, deficiência de B12 e folato, infecções virais, aplasia, infiltração medular, mielodisplasia.','Destruição imune: púrpura trombocitopênica imune, lúpus, HIV, hepatite C, medicamentos, heparina.','Consumo: PTT, síndrome hemolítico-urêmica, CIVD, HELLP, sepse.','Sequestro: hiperesplenismo por hipertensão portal.','Diluição: transfusão maciça.','Na gestação: trombocitopenia gestacional (leve, no terceiro trimestre), pré-eclâmpsia e HELLP.']},
  {h:'As três que não podem passar',table:{head:['Doença','Quando pensar','Conduta inicial'],rows:[['PTT','Plaquetopenia com esquizócitos, LDH alto, com ou sem febre, alteração neurológica e renal','Plasmaférese de urgência e corticoide; ADAMTS13 colhido antes; evitar transfusão de plaquetas'],['HIT','Queda de plaquetas acima de 50%, 5 a 10 dias após início de heparina, com ou sem trombose; escore 4T','Suspender toda heparina e iniciar anticoagulante não heparínico; não esperar o resultado do anticorpo'],['CIVD','Sepse, trauma, neoplasia, complicação obstétrica; TP e TTPa alargados, fibrinogênio baixo, D-dímero alto','Tratar a causa; hemocomponentes se houver sangramento ou procedimento']]}},
  {h:'Púrpura trombocitopênica imune',p:['Diagnóstico de exclusão: plaquetas abaixo de 100 mil, isoladas, com as outras séries e o esfregaço normais. No adulto, pesquise HIV e hepatite C. Trata-se quando há sangramento ou plaquetas abaixo de 30 mil: corticoide por curso curto, com imunoglobulina quando é preciso subir rápido. Acima de 30 mil sem sangramento, a conduta é observar.']},
  {h:'Trombocitose',p:['Acima de 450 mil. A maioria é reacional: ferropenia, infecção, inflamação, pós-operatório, neoplasia, pós-esplenectomia. Trombocitose persistente sem causa, sobretudo acima de 600 mil, pede pesquisa de JAK2, CALR e MPL para trombocitemia essencial. Dose ferritina antes de tudo.']}
 ],
 pitfalls:['Transfundir plaquetas na PTT ou na HIT sem sangramento com risco de vida.','Diagnosticar PTI sem olhar o esfregaço.','Esperar o anticorpo anti-PF4 para suspender a heparina.','Esquecer heparina de baixo peso molecular e a heparina do cateter como fontes.','Investigar trombocitose sem dosar ferritina.'],
 quiz:[
  {q:'Sétimo dia de enoxaparina, plaquetas caem de 240 mil para 95 mil e surge trombose venosa nova. A conduta é:',o:['Aumentar a dose de enoxaparina','Suspender heparina e iniciar anticoagulante não heparínico','Transfundir plaquetas','Trocar por heparina não fracionada'],a:1,why:'Queda acima de 50% no tempo típico, com trombose, torna HIT muito provável. Toda heparina deve ser suspensa.'},
  {q:'Mulher de 30 anos, plaquetas de 18 mil, petéquias, demais séries e esfregaço normais. O diagnóstico mais provável e a conduta são:',o:['PTT; plasmaférese','PTI; corticoide','Aplasia; transplante','CIVD; plasma fresco'],a:1,why:'Plaquetopenia isolada com esfregaço normal e sangramento cutâneo é PTI. Abaixo de 30 mil, trata-se.'},
  {q:'Plaquetas de 780 mil, VCM de 68 fL e ferritina de 6 ng/mL. A trombocitose é mais provavelmente:',o:['Trombocitemia essencial','Reacional à ferropenia','Leucemia mieloide crônica','Erro de laboratório'],a:1,why:'Ferropenia é causa clássica de trombocitose reacional, que regride com a reposição de ferro.'}
 ],refs:['ash2019','isth2020','ash2018hit','guia']},

{id:'m11',layer:'Camada 5 · Integração',title:'Pancitopenia e sinais de alarme',min:20,
 summary:'Três séries baixas: medula que não produz, medula ocupada ou destruição periférica.',
 goals:['Organizar as causas de pancitopenia.','Decidir quando indicar avaliação medular.','Reconhecer os hemogramas que pedem hematologista no mesmo dia.'],
 sections:[
  {h:'Três mecanismos',table:{head:['Mecanismo','Causas','Pistas'],rows:[['Medula vazia','Anemia aplásica, quimioterapia, radiação, medicamentos, hepatite, hemoglobinúria paroxística noturna','Reticulócitos muito baixos, sem esplenomegalia'],['Medula ocupada ou ineficaz','Leucemias agudas, mielodisplasia, mielofibrose, metástase, linfoma, tuberculose, histoplasmose, leishmaniose visceral, deficiência de B12 e folato','Blastos, dacriócitos e eritroblastos circulantes, VCM alto'],['Destruição ou sequestro periférico','Hiperesplenismo, lúpus, sepse, síndrome hemofagocítica','Baço grande, medula celular']]}},
  {h:'Roteiro',list:['Confirme com nova coleta e revise a lâmina.','História: medicamentos, quimioterapia, álcool, dieta, febre, perda de peso, sangramento, viagem e procedência.','Exame: baço, fígado, linfonodos, pele e mucosas.','Exames iniciais: reticulócitos, B12, folato, função hepática, LDH, sorologias para HIV e hepatites, FAN conforme o quadro.','Sem causa clara, ou com blastos e displasia: mielograma e biópsia de medula.']},
  {h:'Leucoeritroblastose',p:['Eritroblastos e granulócitos imaturos no sangue periférico, com dacriócitos, indicam que a medula está sendo ocupada: mielofibrose, metástase óssea, infecção granulomatosa. É indicação de biópsia de medula.']},
  {h:'Hemogramas que não esperam',list:['Blastos no sangue periférico.','Pancitopenia com febre.','Neutrófilos abaixo de 500 com febre.','Plaquetopenia com esquizócitos.','Leucometria acima de 100 mil com sintomas neurológicos ou respiratórios (leucostase).','Pancitopenia com sangramento e alteração do coagulograma: pensar em leucemia promielocítica.','Hemoglobina em queda rápida com sinais de hemólise.']}
 ],
 pitfalls:['Atribuir pancitopenia a uma virose sem repetir o exame.','Esquecer deficiência de B12 como causa reversível de pancitopenia.','Não palpar o baço.','Deixar de pensar em leishmaniose visceral em paciente de área endêmica com febre, baço grande e pancitopenia.','Adiar o contato com a hematologia diante de blastos.'],
 quiz:[
  {q:'Pancitopenia com reticulócitos muito baixos, sem esplenomegalia e sem células anormais na lâmina, em jovem previamente hígido. A hipótese principal é:',o:['Hiperesplenismo','Anemia aplásica','Leucemia mieloide crônica','PTI'],a:1,why:'Medula vazia: três séries baixas, sem resposta reticulocitária e sem baço aumentado.'},
  {q:'Sangue periférico com dacriócitos, eritroblastos e mielócitos em paciente com baço muito aumentado. O achado se chama e sugere:',o:['Desvio à esquerda; infecção','Leucoeritroblastose; ocupação medular','Reação leucemoide; sepse','Anisocitose; ferropenia'],a:1,why:'Formas jovens das duas linhagens com hemácias em lágrima indicam infiltração ou fibrose da medula.'},
  {q:'Pancitopenia, sangramento gengival, fibrinogênio baixo e promielócitos com bastões de Auer. A conduta imediata inclui:',o:['Aguardar a citogenética','Iniciar ácido transretinoico já na suspeita','Apenas transfundir hemácias','Alta com retorno'],a:1,why:'Leucemia promielocítica mata por coagulopatia nos primeiros dias. O tratamento começa na suspeita.'}
 ],refs:['who2022','guia']},

{id:'m12',layer:'Camada 5 · Integração',title:'Esfregaço periférico',min:20,
 summary:'O vocabulário da lâmina e o que cada achado quer dizer.',
 goals:['Associar as alterações de forma das hemácias às suas causas.','Reconhecer inclusões eritrocitárias.','Identificar os achados de leucócitos e plaquetas que mudam a conduta.'],
 sections:[
  {h:'Forma das hemácias',table:{head:['Achado','Como é','Pensar em'],rows:[['Esferócitos','Pequenos, densos, sem palidez central','Hemólise autoimune, esferocitose hereditária'],['Esquizócitos','Fragmentos, em capacete ou triângulo','PTT, SHU, CIVD, prótese valvar, HELLP'],['Dacriócitos','Em lágrima','Mielofibrose, infiltração medular'],['Drepanócitos','Em foice','Doença falciforme'],['Células em alvo','Centro corado','Talassemia, hemoglobinopatia C, hepatopatia, pós-esplenectomia'],['Acantócitos','Espículas irregulares','Hepatopatia grave, abetalipoproteinemia'],['Equinócitos','Espículas curtas e regulares','Uremia, artefato'],['Macro-ovalócitos','Grandes e ovais','Anemia megaloblástica'],['Células mordidas','Com mordida na borda','Deficiência de G6PD'],['Rouleaux','Hemácias empilhadas','Mieloma, inflamação com proteínas altas']]}},
  {h:'Inclusões',table:{head:['Inclusão','Significado'],rows:[['Corpúsculos de Howell-Jolly','Baço ausente ou sem função'],['Pontilhado basofílico grosseiro','Intoxicação por chumbo, talassemia, anemia sideroblástica'],['Corpúsculos de Heinz (coloração especial)','Deficiência de G6PD, hemoglobinas instáveis'],['Corpúsculos de Pappenheimer','Sobrecarga de ferro, anemia sideroblástica, pós-esplenectomia'],['Parasitas','Malária, babesiose'],['Policromasia','Reticulócitos aumentados']]}},
  {h:'Leucócitos e plaquetas',list:['Neutrófilos hipersegmentados (seis lobos ou mais): deficiência de B12 ou folato.','Granulações tóxicas, vacúolos e corpúsculos de Döhle: infecção grave.','Pseudo-Pelger-Huët (núcleo bilobado) e hipogranulação: mielodisplasia.','Linfócitos atípicos: mononucleose e outras viroses.','Manchas de Gumprecht: leucemia linfocítica crônica.','Blastos e bastões de Auer: leucemia aguda, linhagem mieloide quando há bastões.','Agregados plaquetários: pseudotrombocitopenia.','Plaquetas gigantes: PTI e macrotrombocitopenias hereditárias.']},
  {h:'Como usar',p:['O esfregaço não substitui o raciocínio: ele confirma ou derruba uma hipótese que os números levantaram. Peça com a pergunta clínica escrita, por exemplo pesquisa de esquizócitos em paciente com plaquetopenia e LDH alto.']}
 ],
 pitfalls:['Confundir esferócito com esquizócito: o primeiro é inteiro e denso, o segundo é fragmento.','Valorizar poucos esquizócitos isolados sem contexto clínico.','Esquecer que Howell-Jolly sem esplenectomia indica hipoesplenismo funcional.','Pedir lâmina sem dizer o que se procura.','Atribuir rouleaux a anemia quando o problema é excesso de proteína.'],
 quiz:[
  {q:'Corpúsculos de Howell-Jolly em paciente com doença falciforme indicam:',o:['Crise hemolítica','Hipoesplenismo funcional','Infecção por parvovírus','Deficiência de ferro'],a:1,why:'O baço remove restos nucleares. Sua presença indica autoesplenectomia, com risco de infecção por germes encapsulados.'},
  {q:'Rouleaux no esfregaço, anemia, dor óssea e creatinina elevada em idoso. O exame seguinte é:',o:['Ferritina','Eletroforese de proteínas séricas','Coombs direto','Eletroforese de hemoglobina'],a:1,why:'Empilhamento de hemácias por excesso de imunoglobulina, com lesão óssea e renal, sugere mieloma múltiplo.'},
  {q:'Pontilhado basofílico grosseiro com anemia microcítica em trabalhador de fábrica de baterias sugere:',o:['Ferropenia','Intoxicação por chumbo','Traço talassêmico','Deficiência de B12'],a:1,why:'O chumbo inibe enzimas da síntese do heme e a degradação de RNA ribossômico, o que gera o pontilhado.'}
 ],refs:['guia']}
];

const H=['Parâmetro','Resultado','Referência'];
const CASES=[
{id:'c1',focus:'Anemia microcítica',stem:'Mulher de 34 anos, cansaço e queda de cabelo há 4 meses, menstruação abundante.',
 table:{head:H,rows:[['Hemoglobina','8,9 g/dL','12 a 16'],['VCM','71 fL','80 a 100'],['RDW','18,2%','11,5 a 14,5'],['Hemácias','3,9 milhões','4,0 a 5,2'],['Leucócitos','6.200','4.000 a 11.000'],['Plaquetas','512 mil','150 a 450 mil']]},tableTitle:'Hemograma',
 ask:'Classifique a anemia, diga a hipótese principal, o exame que confirma e o que explica as plaquetas.',
 answer:['Anemia microcítica com RDW alto: o padrão é de ferropenia.','Índice de Mentzer: 71 ÷ 3,9 = 18, acima de 13, o que afasta o traço talassêmico.','Confirmar com ferritina; abaixo de 30 ng/mL fecha.','A trombocitose é reacional à ferropenia e regride com a reposição.','Causa provável: perda menstrual. Tratar com ferro oral, manter 3 meses após normalizar, e abordar o sangramento uterino.']},
{id:'c2',focus:'Microcitose sem anemia importante',stem:'Homem de 26 anos, assintomático, exame admissional. Pai com anemia leve desde sempre.',
 table:{head:H,rows:[['Hemoglobina','12,4 g/dL','13 a 17'],['VCM','64 fL','80 a 100'],['RDW','13,4%','11,5 a 14,5'],['Hemácias','6,2 milhões','4,5 a 5,9'],['Ferritina','140 ng/mL','30 a 300']]},tableTitle:'Exames',
 ask:'Qual a hipótese e qual o exame seguinte? Há indicação de ferro?',
 answer:['Microcitose desproporcional ao grau de anemia, com muitas hemácias e RDW normal.','Índice de Mentzer: 64 ÷ 6,2 = 10,3, abaixo de 13.','Ferritina normal afasta ferropenia.','Hipótese: traço talassêmico. Pedir eletroforese de hemoglobina: hemoglobina A2 acima de 3,5% indica traço beta; se normal, pensar em traço alfa.','Não há indicação de ferro. Vale orientação genética.']},
{id:'c3',focus:'Anemia macrocítica',stem:'Mulher de 67 anos, formigamento nos pés, desequilíbrio e esquecimento. Usa metformina há 12 anos.',
 table:{head:H,rows:[['Hemoglobina','9,1 g/dL','12 a 16'],['VCM','121 fL','80 a 100'],['Leucócitos','3.300','4.000 a 11.000'],['Plaquetas','118 mil','150 a 450 mil'],['LDH','1.850 U/L','até 250'],['Bilirrubina indireta','1,9 mg/dL','até 0,8']]},tableTitle:'Exames',
 ask:'Qual a hipótese, o que explica LDH e bilirrubina, e qual erro terapêutico precisa ser evitado?',
 answer:['Anemia macrocítica com pancitopenia leve e quadro neurológico: deficiência de vitamina B12.','LDH e bilirrubina indireta altos vêm da destruição de precursores dentro da medula (eritropoese ineficaz), não de hemólise periférica.','Fatores de risco: metformina por tempo longo e idade, com possível anemia perniciosa. Dosar B12 e, se limítrofe, ácido metilmalônico; pesquisar anticorpo antifator intrínseco.','Erro a evitar: repor só ácido fólico, que melhora o sangue e deixa a lesão neurológica progredir.','Tratar com B12 parenteral e vigiar potássio nos primeiros dias.']},
{id:'c4',focus:'Hemólise',stem:'Mulher de 41 anos com lúpus, icterícia e urina escura há 3 dias.',
 table:{head:H,rows:[['Hemoglobina','6,8 g/dL','12 a 16'],['VCM','104 fL','80 a 100'],['Reticulócitos','14%','0,5 a 2'],['LDH','980 U/L','até 250'],['Haptoglobina','indetectável','30 a 200 mg/dL'],['Plaquetas','210 mil','150 a 450 mil'],['Esfregaço','esferócitos e policromasia','']]},tableTitle:'Exames',
 ask:'Qual o diagnóstico, qual exame confirma e por que o VCM está alto?',
 answer:['Perfil de hemólise: reticulócitos altos, LDH alto, haptoglobina consumida.','Esferócitos em paciente com lúpus: anemia hemolítica autoimune por anticorpos quentes.','Confirmar com Coombs direto, positivo para IgG.','VCM alto pela reticulocitose: reticulócitos são maiores que hemácias maduras.','Plaquetas normais e ausência de esquizócitos afastam microangiopatia. Tratamento inicial: corticoide; reposição de folato.']},
{id:'c5',focus:'Plaquetopenia com hemólise',stem:'Mulher de 38 anos, confusão mental, febre baixa e petéquias há 2 dias.',
 table:{head:H,rows:[['Hemoglobina','7,4 g/dL','12 a 16'],['Plaquetas','14 mil','150 a 450 mil'],['LDH','2.100 U/L','até 250'],['Creatinina','1,4 mg/dL','0,6 a 1,1'],['TP e TTPa','normais',''],['Esfregaço','numerosos esquizócitos','']]},tableTitle:'Exames',
 ask:'Qual a hipótese, o que a separa de CIVD e qual a conduta de urgência?',
 answer:['Anemia hemolítica microangiopática com plaquetopenia grave e alteração neurológica: púrpura trombocitopênica trombótica.','Coagulograma normal afasta CIVD, em que TP e TTPa alargam e o fibrinogênio cai.','Colher ADAMTS13 antes de qualquer plasma, mas não esperar o resultado.','Conduta: plasmaférese de urgência e corticoide.','Não transfundir plaquetas, salvo sangramento com risco de vida.']},
{id:'c6',focus:'Leucocitose',stem:'Homem de 52 anos, cansaço e sensação de peso no lado esquerdo do abdome. Baço palpável a 8 cm.',
 table:{head:H,rows:[['Leucócitos','162 mil','4.000 a 11.000'],['Diferencial','neutrófilos 52%, bastões 12%, metamielócitos 10%, mielócitos 14%, promielócitos 3%, blastos 1%, basófilos 6%, eosinófilos 2%',''],['Hemoglobina','11,2 g/dL','13 a 17'],['Plaquetas','640 mil','150 a 450 mil']]},tableTitle:'Hemograma',
 ask:'Reação leucemoide ou neoplasia? Quais pistas decidem e qual exame confirma?',
 answer:['Leucocitose extrema com todas as fases de maturação granulocítica, do blasto ao segmentado.','Basofilia (6% de 162 mil é quase 10 mil) e esplenomegalia não aparecem em reação a infecção.','Trombocitose associada reforça doença mieloproliferativa.','Hipótese: leucemia mieloide crônica em fase crônica.','Confirmar com pesquisa de BCR-ABL1 ou cromossomo Filadélfia. O tratamento é com inibidor de tirosina quinase.']},
{id:'c7',focus:'Neutropenia febril',stem:'Mulher de 58 anos, décimo dia após quimioterapia para câncer de mama, temperatura de 38,6 °C, sem queixas localizadas.',
 table:{head:H,rows:[['Leucócitos','900','4.000 a 11.000'],['Neutrófilos','18%',''],['Hemoglobina','9,8 g/dL','12 a 16'],['Plaquetas','64 mil','150 a 450 mil']]},tableTitle:'Hemograma',
 ask:'Calcule os neutrófilos, classifique o quadro e descreva a primeira hora.',
 answer:['Neutrófilos absolutos: 18% de 900 = 162 por microlitro. Neutropenia grave.','Febre de 38,6 °C com neutrófilos abaixo de 500: neutropenia febril.','A ausência de foco não tranquiliza: sem neutrófilos, os sinais inflamatórios são pobres.','Primeira hora: duas hemoculturas (incluindo do cateter, se houver), outras culturas conforme o quadro e betalactâmico com ação contra Pseudomonas.','Estratificar o risco para decidir internação e reavaliar em 48 a 72 horas.']},
{id:'c8',focus:'Linfocitose',stem:'Homem de 72 anos, assintomático, exame de rotina. Linfonodos cervicais pequenos e indolores.',
 table:{head:H,rows:[['Leucócitos','46 mil','4.000 a 11.000'],['Linfócitos','84%',''],['Hemoglobina','13,6 g/dL','13 a 17'],['Plaquetas','188 mil','150 a 450 mil'],['Esfregaço','linfócitos pequenos e maduros, manchas de Gumprecht','']]},tableTitle:'Hemograma',
 ask:'Qual a hipótese, o exame que confirma e a conduta se confirmado?',
 answer:['Linfocitose absoluta de cerca de 38.600, com células maduras e restos nucleares esmagados.','Hipótese: leucemia linfocítica crônica.','Confirmar com imunofenotipagem do sangue periférico: população B clonal de pelo menos 5 mil por microlitro. Não é preciso mielograma para o diagnóstico.','Sem anemia, sem plaquetopenia e sem sintomas: estágio inicial.','Conduta: observar e acompanhar. O tratamento é indicado por citopenias, sintomas, crescimento rápido de linfonodos ou baço, ou tempo de duplicação linfocitária curto.']},
{id:'c9',focus:'Pancitopenia',stem:'Homem de 29 anos, procedente do interior do Nordeste, febre há 2 meses, emagrecimento e baço palpável na fossa ilíaca.',
 table:{head:H,rows:[['Hemoglobina','7,2 g/dL','13 a 17'],['Leucócitos','1.900','4.000 a 11.000'],['Plaquetas','72 mil','150 a 450 mil'],['Albumina','2,4 g/dL','3,5 a 5,0'],['Globulinas','5,8 g/dL','2,0 a 3,5']]},tableTitle:'Exames',
 ask:'Qual a principal hipótese infecciosa e como confirmar? Quais diferenciais?',
 answer:['Febre prolongada, esplenomegalia volumosa, pancitopenia e inversão albumina-globulina em paciente de área endêmica.','Hipótese principal: leishmaniose visceral.','Confirmar com teste rápido rK39 e pesquisa de amastigotas no aspirado de medula óssea.','Diferenciais: linfoma, leucemia, tuberculose disseminada, histoplasmose, esquistossomose hepatoesplênica, síndrome hemofagocítica.','Pesquisar HIV: a coinfecção muda o tratamento e o prognóstico.']},
{id:'c10',focus:'Eritrocitose',stem:'Homem de 61 anos, cefaleia, rosto avermelhado e coceira depois do banho. Não fuma. Saturação de 97%.',
 table:{head:H,rows:[['Hemoglobina','19,4 g/dL','13 a 17'],['Hematócrito','58%','40 a 50'],['Leucócitos','13.800','4.000 a 11.000'],['Plaquetas','590 mil','150 a 450 mil'],['Eritropoetina','baixa','']]},tableTitle:'Exames',
 ask:'Qual o diagnóstico provável, o exame que confirma, o principal risco e a meta de tratamento?',
 answer:['Eritrocitose absoluta com leucocitose e trombocitose: panmielose.','Eritropoetina baixa e saturação normal afastam causa secundária por hipóxia.','Prurido aquagênico é pista clássica.','Hipótese: policitemia vera. Confirmar com pesquisa de mutação de JAK2.','Risco principal: trombose arterial e venosa. Tratamento: sangrias para manter o hematócrito abaixo de 45% e aspirina em dose baixa; citorredução nos pacientes de alto risco.']}
];

